const router = require('express').Router();
const path   = require('path');
const db     = require('../patterns/DatabaseSingleton');
const { requireRoles }       = require('../middleware/auth');
const { generarComprobante } = require('../services/ComprobanteService');
const { calculateSaleTotals } = require('../services/VentaCalculator');

// Registrar venta
router.post('/', requireRoles('Administrador', 'Supervisor', 'Vendedor'), async (req, res) => {
  const {
    cliente_id, cliente_nombre, cliente_doc,
    tipo_doc, metodo_pago,
    items,        
    usuario_id,
  } = req.body;

  if (!items || items.length === 0)
    return res.status(400).json({ error: 'La venta debe tener al menos un producto.' });
  if (!['Boleta', 'Factura'].includes(tipo_doc))
    return res.status(400).json({ error: 'Tipo de documento inválido.' });
  if (!['Efectivo', 'Tarjeta', 'Yape/Plin'].includes(metodo_pago))
    return res.status(400).json({ error: 'Método de pago inválido.' });

  let calculatedSale;
  try {
    calculatedSale = calculateSaleTotals(items);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }

  const conn = await db.getConnection();
  try {
    await conn.beginTransaction();

    // 1. Verificar stock
    for (const item of items) {
      const [rows] = await conn.query(
        'SELECT stock, estado FROM productos WHERE id = ? FOR UPDATE',
        [item.producto_id]
      );
      if (rows.length === 0)
        throw new Error(`Producto ${item.producto_id} no encontrado.`);
      if (rows[0].estado === 'vencido')
        throw new Error(`El producto "${item.producto_nombre}" está vencido.`);
      if (rows[0].stock < item.cantidad)
        throw new Error(`Stock insuficiente para "${item.producto_nombre}". Disponible: ${rows[0].stock}.`);
    }

    // Auto-registrar cliente nuevo si no tiene id pero si tiene nombre
    let clienteIdFinal = cliente_id || null;

    if (!cliente_id && cliente_nombre && cliente_nombre.trim() !== '') {
      if (cliente_doc && cliente_doc.trim() !== '') {
        const [existing] = await conn.query(
          'SELECT id FROM clientes WHERE dni = ? LIMIT 1',
          [cliente_doc.trim()]
        );
        if (existing.length > 0) clienteIdFinal = existing[0].id;
      }
      if (!clienteIdFinal) {
        const [inserted] = await conn.query(
          `INSERT INTO clientes (nombre, dni, estado) VALUES (?, ?, 'Activo')`,
          [
            cliente_nombre.trim(),
            (cliente_doc && cliente_doc.trim() !== '') ? cliente_doc.trim() : null,
          ]
        );
        clienteIdFinal = inserted.insertId;
      }
    }

    // Insertar cabecera de venta
    const [ventaResult] = await conn.query(
      `INSERT INTO ventas
         (cliente_id, cliente_nombre, cliente_doc, tipo_doc, metodo_pago, subtotal, igv, total, usuario_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        clienteIdFinal,
        cliente_nombre || 'Consumidor final',
        cliente_doc    || null,
        tipo_doc, metodo_pago,
        calculatedSale.subtotal,
        calculatedSale.igv,
        calculatedSale.total,
        usuario_id || null,
      ]
    );
    const ventaId = ventaResult.insertId;

    // Insertar ítems y descontar stock
    for (const item of calculatedSale.items) {
      await conn.query(
        `INSERT INTO venta_items (venta_id, producto_id, producto_nombre, cantidad, precio_unit, subtotal)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [ventaId, item.producto_id, item.producto_nombre, item.cantidad, item.precio_unit, item.subtotal]
      );
      await conn.query(
        `UPDATE productos
         SET stock = stock - ?,
             estado = CASE
               WHEN (stock - ?) <= 0           THEN 'agotado'
               WHEN (stock - ?) <= stock_minimo THEN 'bajo'
               ELSE 'normal'
             END
         WHERE id = ?`,
        [item.cantidad, item.cantidad, item.cantidad, item.producto_id]
      );
    }

    await conn.commit();

    // Generar PDF
    let pdfNombre = null;
    try {
      const [[ventaCompleta]] = await db.query(
        `SELECT v.*, u.nombre AS vendedor
         FROM ventas v LEFT JOIN usuarios u ON u.id = v.usuario_id
         WHERE v.id = ?`, [ventaId]
      );
      const [ventaItems] = await db.query(
        'SELECT * FROM venta_items WHERE venta_id = ?', [ventaId]
      );
      ventaCompleta.items = ventaItems;
      const rutaPDF = await generarComprobante(ventaCompleta);
      pdfNombre = path.basename(rutaPDF);
    } catch (pdfErr) {
      console.error('[PDF] Error generando comprobante:', pdfErr.message);
    }

    res.status(201).json({
      mensaje:  'Venta registrada correctamente.',
      id:       ventaId,
      pdf:      pdfNombre,
      pdf_url:  pdfNombre ? `/api/ventas/${ventaId}/pdf` : null,
    });

  } catch (err) {
    await conn.rollback();
    res.status(400).json({ error: err.message });
  } finally {
    conn.release();
  }
});

// Listar ventas 
router.get('/', requireRoles('Administrador', 'Supervisor'), async (req, res) => {
  try {
    const [rows] = await db.query(
      `SELECT v.*, u.nombre AS vendedor
       FROM ventas v
       LEFT JOIN usuarios u ON u.id = v.usuario_id
       ORDER BY v.fecha DESC
       LIMIT 200`
    );
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Descargar comprobante 
router.get('/:id/pdf', requireRoles('Administrador', 'Supervisor', 'Vendedor'), async (req, res) => {
  try {
    const [[venta]] = await db.query(
      `SELECT v.*, u.nombre AS vendedor
       FROM ventas v LEFT JOIN usuarios u ON u.id = v.usuario_id
       WHERE v.id = ?`, [req.params.id]
    );
    if (!venta) return res.status(404).json({ error: 'Venta no encontrada.' });

    const [items] = await db.query(
      'SELECT * FROM venta_items WHERE venta_id = ?', [req.params.id]
    );
    venta.items = items;

    // Borra el PDF
    const rutaPDF = await generarComprobante(venta);
    const nombre  = path.basename(rutaPDF);

    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="${nombre}"`);
    res.sendFile(rutaPDF);
  } catch (err) {
    console.error('[PDF] Error al servir comprobante:', err.message);
    res.status(500).json({ error: 'No se pudo generar el PDF.' });
  }
});

// Detalle de venta 
router.get('/:id', requireRoles('Administrador', 'Supervisor', 'Vendedor'), async (req, res) => {
  try {
    const [[venta]] = await db.query('SELECT * FROM ventas WHERE id = ?', [req.params.id]);
    if (!venta) return res.status(404).json({ error: 'Venta no encontrada.' });
    const [items] = await db.query('SELECT * FROM venta_items WHERE venta_id = ?', [req.params.id]);
    res.json({ ...venta, items });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Anular venta y devolver stock 
router.put('/:id/anular', requireRoles('Administrador'), async (req, res) => {
  const conn = await db.getConnection();
  try {
    await conn.beginTransaction();

    const [[venta]] = await conn.query(
      'SELECT * FROM ventas WHERE id = ? FOR UPDATE', [req.params.id]
    );
    if (!venta) throw new Error('Venta no encontrada.');
    if (venta.estado === 'Anulada') throw new Error('La venta ya está anulada.');

    const [items] = await conn.query(
      'SELECT * FROM venta_items WHERE venta_id = ?', [req.params.id]
    );

    for (const item of items) {
      await conn.query(
        `UPDATE productos
         SET stock = stock + ?,
             estado = CASE
               WHEN (stock + ?) > stock_minimo THEN 'normal'
               WHEN (stock + ?) > 0            THEN 'bajo'
               ELSE 'agotado'
             END
         WHERE id = ?`,
        [item.cantidad, item.cantidad, item.cantidad, item.producto_id]
      );
    }

    await conn.query('UPDATE ventas SET estado = ? WHERE id = ?', ['Anulada', req.params.id]);
    await conn.commit();
    res.json({ mensaje: 'Venta anulada y stock restaurado.' });

  } catch (err) {
    await conn.rollback();
    res.status(400).json({ error: err.message });
  } finally {
    conn.release();
  }
});

module.exports = router;

import { useState, useEffect, useCallback } from 'react';
import { apiClient } from '../utils/apiClient';
import { Plus, Edit, Trash2, X, Building2, Pill, Globe, AlertTriangle, Loader2 } from 'lucide-react';


interface Laboratorio { id: number; nombre: string; pais: string; contacto?: string; telefono?: string; productos: number; }
interface Categoria { id: number; nombre: string; descripcion?: string; productos: number; }

const inp = 'w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg px-4 py-2 text-white placeholder:text-muted-foreground focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors';
const lbl = 'block text-sm text-muted-foreground mb-2';

// Modal Laboratorio 
function LabModal({ isOpen, onClose, onSave, item, mode }: any) {
  const [form, setForm] = useState({ nombre: '', pais: '', contacto: '', telefono: '' });
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    if (isOpen) {
      setForm(mode === 'edit' && item ? { nombre: item.nombre, pais: item.pais, contacto: item.contacto || '', telefono: item.telefono || '' } : { nombre: '', pais: '', contacto: '', telefono: '' });
      setErrors({});
    }
  }, [isOpen, mode, item]);

  if (!isOpen) return null;
  const s = (f: string, v: string) => setForm(p => ({ ...p, [f]: v }));
  const validate = () => {
    const e: Record<string, string> = {};
    if (!form.nombre.trim()) e.nombre = 'El nombre es obligatorio';
    if (!form.pais.trim()) e.pais = 'El país es obligatorio';
    return e;
  };
  const handleSubmit = () => {
    const e = validate();
    if (Object.keys(e).length > 0) { setErrors(e); return; }
    onSave({ ...form, ...(mode === 'edit' && item ? { id: item.id, productos: item.productos } : { productos: 0 }) });
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl w-full max-w-md">
        <div className="border-b border-[oklch(0.269_0_0)] px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3"><div className="p-2 bg-[oklch(0.488_0.243_264.376)]/10 rounded-lg"><Building2 className="w-6 h-6 text-[oklch(0.488_0.243_264.376)]" /></div><h2 className="text-xl text-white">{mode === 'create' ? 'Nuevo Laboratorio' : 'Editar Laboratorio'}</h2></div>
          <button onClick={onClose} className="text-muted-foreground hover:text-white"><X className="w-5 h-5" /></button>
        </div>
        <div className="p-6 space-y-4">
          <div><label className={lbl}>Nombre *</label><input className={inp} value={form.nombre} onChange={e => s('nombre', e.target.value)} placeholder="Ej: Bayer" />{errors.nombre && <p className="text-destructive text-xs mt-1">{errors.nombre}</p>}</div>
          <div><label className={lbl}>País *</label><div className="relative"><Globe className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" /><input className={inp + ' pl-10'} value={form.pais} onChange={e => s('pais', e.target.value)} placeholder="Ej: Alemania" /></div>{errors.pais && <p className="text-destructive text-xs mt-1">{errors.pais}</p>}</div>
          <div><label className={lbl}>Contacto</label><input className={inp} value={form.contacto} onChange={e => s('contacto', e.target.value)} placeholder="Nombre del representante" /></div>
          <div><label className={lbl}>Teléfono</label><input className={inp} value={form.telefono} onChange={e => s('telefono', e.target.value)} placeholder="+51 999 000 000" /></div>
        </div>
        <div className="border-t border-[oklch(0.269_0_0)] px-6 py-4 flex gap-3">
          <button onClick={handleSubmit} className="flex-1 bg-[oklch(0.488_0.243_264.376)] hover:bg-[oklch(0.438_0.243_264.376)] text-white py-3 rounded-lg transition-colors">{mode === 'create' ? 'Crear' : 'Guardar'}</button>
          <button onClick={onClose} className="flex-1 bg-[oklch(0.269_0_0)] hover:bg-[oklch(0.318_0_0)] text-white py-3 rounded-lg transition-colors">Cancelar</button>
        </div>
      </div>
    </div>
  );
}

// Modal Categoría 
function CatModal({ isOpen, onClose, onSave, item, mode }: any) {
  const [form, setForm] = useState({ nombre: '', descripcion: '' });
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    if (isOpen) {
      setForm(mode === 'edit' && item ? { nombre: item.nombre, descripcion: item.descripcion || '' } : { nombre: '', descripcion: '' });
      setErrors({});
    }
  }, [isOpen, mode, item]);

  if (!isOpen) return null;
  const s = (f: string, v: string) => setForm(p => ({ ...p, [f]: v }));
  const handleSubmit = () => {
    if (!form.nombre.trim()) { setErrors({ nombre: 'El nombre es obligatorio' }); return; }
    onSave({ ...form, ...(mode === 'edit' && item ? { id: item.id, productos: item.productos } : { productos: 0 }) });
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl w-full max-w-md">
        <div className="border-b border-[oklch(0.269_0_0)] px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3"><div className="p-2 bg-[oklch(0.488_0.243_264.376)]/10 rounded-lg"><Pill className="w-6 h-6 text-[oklch(0.488_0.243_264.376)]" /></div><h2 className="text-xl text-white">{mode === 'create' ? 'Nueva Categoría' : 'Editar Categoría'}</h2></div>
          <button onClick={onClose} className="text-muted-foreground hover:text-white"><X className="w-5 h-5" /></button>
        </div>
        <div className="p-6 space-y-4">
          <div><label className={lbl}>Nombre *</label><input className={inp} value={form.nombre} onChange={e => s('nombre', e.target.value)} placeholder="Ej: Analgésicos" />{errors.nombre && <p className="text-destructive text-xs mt-1">{errors.nombre}</p>}</div>
          <div><label className={lbl}>Descripción</label><textarea className={inp + ' resize-none'} rows={3} value={form.descripcion} onChange={e => s('descripcion', e.target.value)} placeholder="Descripción..." /></div>
        </div>
        <div className="border-t border-[oklch(0.269_0_0)] px-6 py-4 flex gap-3">
          <button onClick={handleSubmit} className="flex-1 bg-[oklch(0.488_0.243_264.376)] hover:bg-[oklch(0.438_0.243_264.376)] text-white py-3 rounded-lg transition-colors">{mode === 'create' ? 'Crear' : 'Guardar'}</button>
          <button onClick={onClose} className="flex-1 bg-[oklch(0.269_0_0)] hover:bg-[oklch(0.318_0_0)] text-white py-3 rounded-lg transition-colors">Cancelar</button>
        </div>
      </div>
    </div>
  );
}

function DelModal({ isOpen, onClose, onConfirm, nombre }: any) {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl max-w-md w-full">
        <div className="border-b border-[oklch(0.269_0_0)] px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3"><div className="p-2 bg-destructive/10 rounded-lg"><AlertTriangle className="w-6 h-6 text-destructive" /></div><h2 className="text-xl text-white">Confirmar Eliminación</h2></div>
          <button onClick={onClose} className="text-muted-foreground hover:text-white"><X className="w-5 h-5" /></button>
        </div>
        <div className="p-6"><p className="text-white mb-4">¿Eliminar <strong>{nombre}</strong>?</p><p className="text-xs text-muted-foreground">⚠️ Esta acción no se puede deshacer.</p></div>
        <div className="border-t border-[oklch(0.269_0_0)] px-6 py-4 flex gap-3">
          <button onClick={onConfirm} className="flex-1 bg-destructive hover:bg-destructive/90 text-white py-3 rounded-lg transition-colors">Eliminar</button>
          <button onClick={onClose} className="flex-1 bg-[oklch(0.269_0_0)] hover:bg-[oklch(0.318_0_0)] text-white py-3 rounded-lg transition-colors">Cancelar</button>
        </div>
      </div>
    </div>
  );
}

export default function Catalogos() {
  const [laboratorios, setLaboratorios] = useState<Laboratorio[]>([]);
  const [categorias, setCategorias] = useState<Categoria[]>([]);
  const [loadingLab, setLoadingLab] = useState(true);
  const [loadingCat, setLoadingCat] = useState(true);

  const [labModal, setLabModal] = useState(false);
  const [labDelModal, setLabDelModal] = useState(false);
  const [labMode, setLabMode] = useState<'create' | 'edit'>('create');
  const [selLab, setSelLab] = useState<Laboratorio | null>(null);

  const [catModal, setCatModal] = useState(false);
  const [catDelModal, setCatDelModal] = useState(false);
  const [catMode, setCatMode] = useState<'create' | 'edit'>('create');
  const [selCat, setSelCat] = useState<Categoria | null>(null);

  const [successMessage, setSuccessMessage] = useState('');
  const [errorMessage, setErrorMessage] = useState('');

  const showMsg = (msg: string) => { setSuccessMessage(msg); setTimeout(() => setSuccessMessage(''), 3000); };
  const showErr = useCallback((msg: string) => {
    setErrorMessage(msg);
    setTimeout(() => setErrorMessage(''), 3000);
  }, []);

  const fetchLabs = useCallback(async () => {
    try {
      setLoadingLab(true);

      const r = await apiClient('/api/laboratorios');

      setLaboratorios(await r.json());

    } catch {
      showErr('Error al cargar laboratorios');
    } finally {
      setLoadingLab(false);
    }
  }, [showErr]);

  const fetchCats = useCallback(async () => {
    try {
      setLoadingCat(true);

      const r = await apiClient('/api/categorias');

      setCategorias(await r.json());

    } catch {
      showErr('Error al cargar categorías');
    } finally {
      setLoadingCat(false);
    }
  }, [showErr]);

  useEffect(() => { fetchLabs(); fetchCats(); }, [fetchLabs, fetchCats]);

  // CRUD Laboratorios
  const saveLab = async (data: any) => {
    try {

      if (labMode === 'create') {

        await apiClient('/api/laboratorios', {
          method: 'POST',
          body: JSON.stringify(data),
        });

        showMsg('Laboratorio creado');

      } else {

        await apiClient(`/api/laboratorios/${data.id}`, {
          method: 'PUT',
          body: JSON.stringify(data),
        });

        showMsg('Laboratorio actualizado');
      }

      setLabModal(false);

      await fetchLabs();

    } catch {
      showErr('Error al guardar laboratorio');
    }
  };

  const deleteLab = async () => {
    if (!selLab) return;

    try {

      await apiClient(`/api/laboratorios/${selLab.id}`, {
        method: 'DELETE',
      });

      await fetchLabs();

      setLabDelModal(false);

      setSelLab(null);

      showMsg('Laboratorio eliminado');

    } catch {
      showErr('Error al eliminar laboratorio');
    }
  };

  // CRUD Categorías
  const saveCat = async (data: any) => {
    try {

      if (catMode === 'create') {

        await apiClient('/api/categorias', {
          method: 'POST',
          body: JSON.stringify(data),
        });

        showMsg('Categoría creada');

      } else {

        await apiClient(`/api/categorias/${data.id}`, {
          method: 'PUT',
          body: JSON.stringify(data),
        });

        showMsg('Categoría actualizada');
      }

      setCatModal(false);

      await fetchCats();

    } catch {
      showErr('Error al guardar categoría');
    }
  };

  const deleteCat = async () => {
    if (!selCat) return;

    try {

      await apiClient(`/api/categorias/${selCat.id}`, {
        method: 'DELETE',
      });

      await fetchCats();

      setCatDelModal(false);

      setSelCat(null);

      showMsg('Categoría eliminada');

    } catch {
      showErr('Error al eliminar categoría');
    }
  };

  return (
    <div className="p-8 space-y-6">
      <div><h2 className="text-2xl text-white mb-1">Catálogos</h2><p className="text-muted-foreground">Gestión de laboratorios y categorías</p></div>

      {successMessage && <div className="bg-[oklch(0.696_0.17_162.48)]/20 border border-[oklch(0.696_0.17_162.48)] rounded-lg p-4 flex items-center justify-between"><p className="text-[oklch(0.696_0.17_162.48)]">{successMessage}</p><button onClick={() => setSuccessMessage('')}><X className="w-5 h-5 text-[oklch(0.696_0.17_162.48)]" /></button></div>}
      {errorMessage && <div className="bg-destructive/20 border border-destructive rounded-lg p-4 flex items-center justify-between"><p className="text-destructive">{errorMessage}</p><button onClick={() => setErrorMessage('')}><X className="w-5 h-5 text-destructive" /></button></div>}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Laboratorios */}
        <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-6">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2"><Building2 className="w-5 h-5 text-[oklch(0.488_0.243_264.376)]" /><h3 className="text-lg text-white">Laboratorios</h3><span className="px-2 py-0.5 bg-[oklch(0.269_0_0)] text-muted-foreground rounded-full text-xs">{laboratorios.length}</span></div>
            <button onClick={() => { setLabMode('create'); setSelLab(null); setLabModal(true); }} className="flex items-center gap-1 px-3 py-1.5 bg-[oklch(0.488_0.243_264.376)] hover:bg-[oklch(0.438_0.243_264.376)] text-white rounded-lg transition-colors text-sm"><Plus className="w-4 h-4" />Nuevo</button>
          </div>
          {loadingLab ? <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 text-[oklch(0.488_0.243_264.376)] animate-spin" /></div> : (
            <div className="space-y-3">
              {laboratorios.map(lab => (
                <div key={lab.id} className="bg-[oklch(0.269_0_0)] rounded-lg p-4 hover:bg-[oklch(0.318_0_0)] transition-colors">
                  <div className="flex items-start justify-between">
                    <div className="flex-1 min-w-0"><p className="text-white mb-0.5">{lab.nombre}</p><p className="text-xs text-muted-foreground">{lab.pais}</p>{lab.contacto && <p className="text-xs text-muted-foreground mt-0.5">{lab.contacto}</p>}</div>
                    <div className="flex items-center gap-2 ml-3 flex-shrink-0">
                      <span className="px-3 py-1 bg-[oklch(0.488_0.243_264.376)]/20 text-[oklch(0.488_0.243_264.376)] rounded-full text-xs whitespace-nowrap">{lab.productos} productos</span>
                      <button onClick={() => { setLabMode('edit'); setSelLab(lab); setLabModal(true); }} className="p-1.5 text-muted-foreground hover:text-[oklch(0.769_0.188_70.08)] transition-colors"><Edit className="w-3.5 h-3.5" /></button>
                      <button onClick={() => { setSelLab(lab); setLabDelModal(true); }} className="p-1.5 text-muted-foreground hover:text-destructive transition-colors"><Trash2 className="w-3.5 h-3.5" /></button>
                    </div>
                  </div>
                </div>
              ))}
              {laboratorios.length === 0 && <p className="text-center text-muted-foreground py-8">No hay laboratorios registrados</p>}
            </div>
          )}
        </div>

        {/* Categorías */}
        <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-6">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2"><Pill className="w-5 h-5 text-[oklch(0.488_0.243_264.376)]" /><h3 className="text-lg text-white">Categorías</h3><span className="px-2 py-0.5 bg-[oklch(0.269_0_0)] text-muted-foreground rounded-full text-xs">{categorias.length}</span></div>
            <button onClick={() => { setCatMode('create'); setSelCat(null); setCatModal(true); }} className="flex items-center gap-1 px-3 py-1.5 bg-[oklch(0.488_0.243_264.376)] hover:bg-[oklch(0.438_0.243_264.376)] text-white rounded-lg transition-colors text-sm"><Plus className="w-4 h-4" />Nueva</button>
          </div>
          {loadingCat ? <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 text-[oklch(0.488_0.243_264.376)] animate-spin" /></div> : (
            <div className="space-y-3">
              {categorias.map(cat => (
                <div key={cat.id} className="bg-[oklch(0.269_0_0)] rounded-lg p-4 hover:bg-[oklch(0.318_0_0)] transition-colors">
                  <div className="flex items-start justify-between">
                    <div className="flex-1 min-w-0"><p className="text-white mb-0.5">{cat.nombre}</p>{cat.descripcion && <p className="text-xs text-muted-foreground">{cat.descripcion}</p>}</div>
                    <div className="flex items-center gap-2 ml-3 flex-shrink-0">
                      <span className="px-3 py-1 bg-[oklch(0.488_0.243_264.376)]/20 text-[oklch(0.488_0.243_264.376)] rounded-full text-xs whitespace-nowrap">{cat.productos} productos</span>
                      <button onClick={() => { setCatMode('edit'); setSelCat(cat); setCatModal(true); }} className="p-1.5 text-muted-foreground hover:text-[oklch(0.769_0.188_70.08)] transition-colors"><Edit className="w-3.5 h-3.5" /></button>
                      <button onClick={() => { setSelCat(cat); setCatDelModal(true); }} className="p-1.5 text-muted-foreground hover:text-destructive transition-colors"><Trash2 className="w-3.5 h-3.5" /></button>
                    </div>
                  </div>
                </div>
              ))}
              {categorias.length === 0 && <p className="text-center text-muted-foreground py-8">No hay categorías registradas</p>}
            </div>
          )}
        </div>
      </div>

      <LabModal isOpen={labModal} onClose={() => { setLabModal(false); setSelLab(null); }} onSave={saveLab} item={selLab} mode={labMode} />
      <DelModal isOpen={labDelModal} onClose={() => setLabDelModal(false)} onConfirm={deleteLab} nombre={selLab?.nombre || ''} />
      <CatModal isOpen={catModal} onClose={() => { setCatModal(false); setSelCat(null); }} onSave={saveCat} item={selCat} mode={catMode} />
      <DelModal isOpen={catDelModal} onClose={() => setCatDelModal(false)} onConfirm={deleteCat} nombre={selCat?.nombre || ''} />
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { apiClient } from '../utils/apiClient';
import {
  Search, Plus, Edit, Trash2, Eye, X, Filter,
  UserCircle2, Users, UserCheck, UserX, Loader2,
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';

interface Cliente {
  id: number;
  nombre: string;
  dni?: string;
  direccion?: string;
  telefono?: string;
  estado: 'Activo' | 'Inactivo';
  fecha_registro?: string;
}

const EMPTY_CLIENT_FORM = { nombre: '', dni: '', direccion: '', telefono: '', estado: 'Activo' };
const inp = 'w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg px-4 py-2 text-white placeholder:text-muted-foreground focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors';
const lbl = 'block text-sm text-muted-foreground mb-2';

// Modal Formulario 
function ClienteFormModal({ isOpen, onClose, onSave, cliente, mode }: any) {
  const [form, setForm] = useState(EMPTY_CLIENT_FORM);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (isOpen) {
      if (mode === 'edit' && cliente) {
        setForm({
          nombre: cliente.nombre ?? '',
          dni: cliente.dni ?? '',
          direccion: cliente.direccion ?? '',
          telefono: cliente.telefono ?? '',
          estado: cliente.estado ?? 'Activo',
        });
      } else {
        setForm(EMPTY_CLIENT_FORM);
      }
      setErrors({});
    }
  }, [isOpen, mode, cliente]);

  if (!isOpen) return null;

  const s = (f: string, v: string) => setForm(p => ({ ...p, [f]: v }));

  const validate = () => {
    const e: Record<string, string> = {};
    if (!form.nombre.trim()) e.nombre = 'El nombre es obligatorio';
    if (form.dni && !/^\d{8}$/.test(form.dni.trim())) e.dni = 'El DNI debe tener 8 dígitos';
    if (form.telefono && !/^[\d\s+\-()]{7,20}$/.test(form.telefono))
      e.telefono = 'Teléfono inválido';
    return e;
  };

  const handleSubmit = async () => {
    const e = validate();
    if (Object.keys(e).length > 0) { setErrors(e); return; }
    setSaving(true);
    await onSave({ ...form, ...(mode === 'edit' && cliente ? { id: cliente.id } : {}) });
    setSaving(false);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl w-full max-w-lg max-h-[90vh] flex flex-col">
        {/* Header */}
        <div className="border-b border-[oklch(0.269_0_0)] px-6 py-4 flex items-center justify-between flex-shrink-0">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-[oklch(0.696_0.17_162.48)]/10 rounded-lg">
              <UserCircle2 className="w-6 h-6 text-[oklch(0.696_0.17_162.48)]" />
            </div>
            <h2 className="text-xl text-white">{mode === 'create' ? 'Nuevo Cliente' : 'Editar Cliente'}</h2>
          </div>
          <button onClick={onClose} className="text-muted-foreground hover:text-white transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 overflow-y-auto space-y-4">
          <div>
            <label className={lbl}>Nombre completo *</label>
            <input className={inp} value={form.nombre} onChange={e => s('nombre', e.target.value)} placeholder="Ej: Juan García López" />
            {errors.nombre && <p className="text-destructive text-xs mt-1">{errors.nombre}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className={lbl}>DNI</label>
              <input className={inp} value={form.dni} onChange={e => s('dni', e.target.value)} placeholder="12345678" maxLength={8} />
              {errors.dni && <p className="text-destructive text-xs mt-1">{errors.dni}</p>}
            </div>
            <div>
              <label className={lbl}>Teléfono</label>
              <input className={inp} value={form.telefono} onChange={e => s('telefono', e.target.value)} placeholder="+51 999 000 000" />
              {errors.telefono && <p className="text-destructive text-xs mt-1">{errors.telefono}</p>}
            </div>
          </div>

          <div>
            <label className={lbl}>Dirección</label>
            <input className={inp} value={form.direccion} onChange={e => s('direccion', e.target.value)} placeholder="Av. Los Pinos 123, Trujillo" />
          </div>

          <div>
            <label className={lbl}>Estado</label>
            <select className={inp + ' appearance-none'} value={form.estado} onChange={e => s('estado', e.target.value)}>
              <option value="Activo" className="bg-[oklch(0.269_0_0)]">Activo</option>
              <option value="Inactivo" className="bg-[oklch(0.269_0_0)]">Inactivo</option>
            </select>
          </div>
        </div>

        {/* Footer */}
        <div className="border-t border-[oklch(0.269_0_0)] px-6 py-4 flex gap-3 flex-shrink-0">
          <button
            onClick={handleSubmit}
            disabled={saving}
            className="flex-1 bg-[oklch(0.696_0.17_162.48)] hover:bg-[oklch(0.646_0.17_162.48)] disabled:opacity-50 text-white py-3 rounded-lg transition-colors flex items-center justify-center gap-2"
          >
            {saving && <Loader2 className="w-4 h-4 animate-spin" />}
            {mode === 'create' ? 'Crear Cliente' : 'Guardar Cambios'}
          </button>
          <button onClick={onClose} className="flex-1 bg-[oklch(0.269_0_0)] hover:bg-[oklch(0.318_0_0)] text-white py-3 rounded-lg transition-colors">
            Cancelar
          </button>
        </div>
      </div>
    </div>
  );
}

// Modal Detalles 
function ClienteDetailsModal({ isOpen, onClose, cliente }: any) {
  if (!isOpen || !cliente) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl w-full max-w-md">
        {/* Header */}
        <div className="border-b border-[oklch(0.269_0_0)] px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-full bg-[oklch(0.696_0.17_162.48)]/20 flex items-center justify-center">
              <UserCircle2 className="w-6 h-6 text-[oklch(0.696_0.17_162.48)]" />
            </div>
            <div>
              <h2 className="text-white font-medium">{cliente.nombre}</h2>
              <p className="text-xs text-muted-foreground">
                {cliente.dni ? `DNI: ${cliente.dni}` : 'Sin DNI registrado'}
              </p>
            </div>
          </div>
          <button onClick={onClose} className="text-muted-foreground hover:text-white transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <div className="bg-[oklch(0.269_0_0)] p-4 rounded-lg">
              <p className="text-xs text-muted-foreground mb-1">Estado</p>
              <span className={`px-3 py-1 rounded-full text-xs ${cliente.estado === 'Activo'
                ? 'bg-[oklch(0.696_0.17_162.48)]/20 text-[oklch(0.696_0.17_162.48)]'
                : 'bg-[oklch(0.269_0_0)] text-muted-foreground border border-[oklch(0.318_0_0)]'}`}>
                {cliente.estado}
              </span>
            </div>
            <div className="bg-[oklch(0.269_0_0)] p-4 rounded-lg">
              <p className="text-xs text-muted-foreground mb-1">Fecha de registro</p>
              <p className="text-white text-sm">
                {cliente.fecha_registro
                  ? new Date(cliente.fecha_registro).toLocaleDateString('es-PE')
                  : '—'}
              </p>
            </div>
          </div>
          {cliente.telefono && (
            <div className="bg-[oklch(0.269_0_0)] p-4 rounded-lg">
              <p className="text-xs text-muted-foreground mb-1">Teléfono</p>
              <p className="text-white">{cliente.telefono}</p>
            </div>
          )}
          {cliente.direccion && (
            <div className="bg-[oklch(0.269_0_0)] p-4 rounded-lg">
              <p className="text-xs text-muted-foreground mb-1">Dirección</p>
              <p className="text-white">{cliente.direccion}</p>
            </div>
          )}
        </div>

        <div className="border-t border-[oklch(0.269_0_0)] px-6 py-4">
          <button onClick={onClose} className="w-full bg-[oklch(0.269_0_0)] hover:bg-[oklch(0.318_0_0)] text-white py-3 rounded-lg transition-colors">
            Cerrar
          </button>
        </div>
      </div>
    </div>
  );
}

// Modal Confirmación Eliminar 
function DeleteModal({ isOpen, onClose, onConfirm, nombre }: any) {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl w-full max-w-sm p-6 space-y-4">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-destructive/10 rounded-lg">
            <Trash2 className="w-6 h-6 text-destructive" />
          </div>
          <h2 className="text-white text-lg">Eliminar cliente</h2>
        </div>
        <p className="text-muted-foreground text-sm">
          ¿Estás seguro de que deseas eliminar a <span className="text-white font-medium">{nombre}</span>? Esta acción no se puede deshacer.
        </p>
        <div className="flex gap-3">
          <button onClick={onConfirm} className="flex-1 bg-destructive hover:bg-destructive/80 text-white py-3 rounded-lg transition-colors">
            Eliminar
          </button>
          <button onClick={onClose} className="flex-1 bg-[oklch(0.269_0_0)] hover:bg-[oklch(0.318_0_0)] text-white py-3 rounded-lg transition-colors">
            Cancelar
          </button>
        </div>
      </div>
    </div>
  );
}

// Componente principal
export default function Clientes() {
  const { usuario } = useAuth();
  const rol = usuario?.rol ?? 'Vendedor';

  const [clientes, setClientes] = useState<Cliente[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterEstado, setFilterEstado] = useState('todos');

  const [selectedCliente, setSelectedCliente] = useState<Cliente | null>(null);
  const [isFormOpen, setIsFormOpen]     = useState(false);
  const [isDetailsOpen, setIsDetailsOpen] = useState(false);
  const [isDeleteOpen, setIsDeleteOpen] = useState(false);
  const [formMode, setFormMode]         = useState<'create' | 'edit'>('create');

  const [successMessage, setSuccessMessage] = useState('');
  const [errorMessage, setErrorMessage]     = useState('');

  const showMsg = (msg: string) => { setSuccessMessage(msg); setTimeout(() => setSuccessMessage(''), 4000); };
  const showErr = useCallback((msg: string) => {
    setErrorMessage(msg);
    setTimeout(() => setErrorMessage(''), 5000);
  }, []);

  const fetchClientes = useCallback(async () => {
    setLoading(true);
    try {
      const res = await apiClient('/api/clientes');
      if (!res.ok) throw new Error();
      const data = await res.json();
      setClientes(data);
    } catch {
      showErr('Error al cargar los clientes');
    } finally {
      setLoading(false);
    }
  }, [showErr]);

  useEffect(() => { fetchClientes(); }, [fetchClientes]);

  const handleSave = async (data: any) => {
    try {
      if (data.id) {
        const res = await apiClient(`/api/clientes/${data.id}`, {
          method: 'PUT',
          body: JSON.stringify(data),
        });
        if (!res.ok) {
          const err = await res.json();
          throw new Error(err.error ?? 'Error desconocido');
        }
        showMsg('Cliente actualizado correctamente');
      } else {
        const res = await apiClient('/api/clientes', {
          method: 'POST',
          body: JSON.stringify(data),
        });
        if (!res.ok) {
          const err = await res.json();
          throw new Error(err.error ?? 'Error desconocido');
        }
        showMsg('Cliente creado correctamente');
      }
      setIsFormOpen(false);
      setSelectedCliente(null);
      await fetchClientes();
    } catch (e: any) {
      showErr(e.message || 'Error al guardar el cliente');
    }
  };

  const handleDelete = async () => {
    if (!selectedCliente) return;
    try {
      const res = await apiClient(`/api/clientes/${selectedCliente.id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error();
      await fetchClientes();
      setIsDeleteOpen(false);
      setSelectedCliente(null);
      showMsg('Cliente eliminado correctamente');
    } catch {
      showErr('Error al eliminar el cliente');
    }
  };

  const filtered = clientes.filter(c => {
    const q = searchTerm.toLowerCase();
    const matchSearch =
      c.nombre.toLowerCase().includes(q) ||
      (c.dni ?? '').includes(q) ||
      (c.telefono ?? '').includes(q);
    return matchSearch && (filterEstado === 'todos' || c.estado === filterEstado);
  });

  const canEdit   = rol === 'Administrador' || rol === 'Supervisor';
  const canDelete = rol === 'Administrador';

  return (
    <div className="p-8 space-y-6">
      {/* Encabezado */}
      <div className="flex items-start justify-between">
        <div>
          <h2 className="text-2xl text-white mb-1">Clientes</h2>
          <p className="text-muted-foreground">Gestión del directorio de clientes</p>
        </div>
        {canEdit && (
          <button
            onClick={() => { setFormMode('create'); setSelectedCliente(null); setIsFormOpen(true); }}
            className="bg-[oklch(0.696_0.17_162.48)] hover:bg-[oklch(0.646_0.17_162.48)] text-white px-4 py-2 rounded-lg transition-colors flex items-center gap-2"
          >
            <Plus className="w-5 h-5" />
            Nuevo Cliente
          </button>
        )}
      </div>

      {/* Tarjetas resumen */}
      <div className="grid grid-cols-3 gap-4">
        <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-4">
          <div className="flex items-center gap-2 mb-1">
            <Users className="w-4 h-4 text-muted-foreground" />
            <p className="text-sm text-muted-foreground">Total</p>
          </div>
          <p className="text-2xl text-white">{clientes.length}</p>
        </div>
        <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-4">
          <div className="flex items-center gap-2 mb-1">
            <UserCheck className="w-4 h-4 text-muted-foreground" />
            <p className="text-sm text-muted-foreground">Activos</p>
          </div>
          <p className="text-2xl text-[oklch(0.696_0.17_162.48)]">
            {clientes.filter(c => c.estado === 'Activo').length}
          </p>
        </div>
        <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-4">
          <div className="flex items-center gap-2 mb-1">
            <UserX className="w-4 h-4 text-muted-foreground" />
            <p className="text-sm text-muted-foreground">Inactivos</p>
          </div>
          <p className="text-2xl text-muted-foreground">
            {clientes.filter(c => c.estado === 'Inactivo').length}
          </p>
        </div>
      </div>

      {/* Mensajes */}
      {successMessage && (
        <div className="bg-[oklch(0.696_0.17_162.48)]/20 border border-[oklch(0.696_0.17_162.48)] rounded-lg p-4 flex items-center justify-between">
          <p className="text-[oklch(0.696_0.17_162.48)]">{successMessage}</p>
          <button onClick={() => setSuccessMessage('')}><X className="w-5 h-5 text-[oklch(0.696_0.17_162.48)]" /></button>
        </div>
      )}
      {errorMessage && (
        <div className="bg-destructive/20 border border-destructive rounded-lg p-4 flex items-center justify-between">
          <p className="text-destructive">{errorMessage}</p>
          <button onClick={() => setErrorMessage('')}><X className="w-5 h-5 text-destructive" /></button>
        </div>
      )}

      {/* Filtros */}
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className={lbl}>Buscar</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
              <input
                type="text"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                placeholder="Nombre, DNI o teléfono..."
                className="w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg pl-11 pr-4 py-2 text-white placeholder:text-muted-foreground focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors"
              />
            </div>
          </div>
          <div>
            <label className={lbl}>Estado</label>
            <div className="relative">
              <Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
              <select
                value={filterEstado}
                onChange={e => setFilterEstado(e.target.value)}
                className="w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg pl-11 pr-4 py-2 text-white focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors appearance-none"
              >
                <option value="todos" className="bg-[oklch(0.269_0_0)]">Todos</option>
                <option value="Activo" className="bg-[oklch(0.269_0_0)]">Activo</option>
                <option value="Inactivo" className="bg-[oklch(0.269_0_0)]">Inactivo</option>
              </select>
            </div>
          </div>
        </div>
      </div>

      {/* Tabla */}
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl overflow-hidden">
        {loading ? (
          <div className="flex items-center justify-center py-20 gap-3">
            <Loader2 className="w-6 h-6 text-[oklch(0.696_0.17_162.48)] animate-spin" />
            <p className="text-muted-foreground">Cargando clientes...</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-[oklch(0.269_0_0)]">
                <tr>
