// Componente Principal
export default function Compras() {
  const [compras, setCompras] = useState<Compra[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterEstado, setFilterEstado] = useState('todos');
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [formMode, setFormMode] = useState<'create' | 'edit'>('create');
  const [selectedCompra, setSelectedCompra] = useState<Compra | null>(null);
  const [successMessage, setSuccessMessage] = useState('');
  const [errorMessage, setErrorMessage] = useState('');

  const fetchCompras = async () => {
    try {
      setLoading(true);
      const res = await apiClient('/api/compras');
      if (!res.ok) throw new Error();
      setCompras(await res.json());
    } catch { setErrorMessage('No se pudo conectar con el servidor'); }
    finally { setLoading(false); }
  };

  useEffect(() => { fetchCompras(); }, []);

  const showMsg = (msg: string) => { setSuccessMessage(msg); setTimeout(() => setSuccessMessage(''), 3000); };
  const showErr = (msg: string) => { setErrorMessage(msg); setTimeout(() => setErrorMessage(''), 3000); };

  const handleSave = async (data: any) => {
    try {
      if (formMode === 'create') {
        const id = `C${String(compras.length + 1).padStart(3, '0')}`;
        const res = await apiClient('/api/compras', {
          method: 'POST',
          body: JSON.stringify({ ...data, id }),
        });
        if (!res.ok) throw new Error();
        showMsg('Compra registrada exitosamente');
      } else {
        const res = await apiClient(`/api/compras/${data.id}`, {
          method: 'PUT',
          body: JSON.stringify(data),
        });
        if (!res.ok) throw new Error();
        showMsg('Compra actualizada correctamente');
      }
      setIsFormModalOpen(false);
      await fetchCompras();
    } catch { showErr('Error al guardar la compra'); }
  };

  const handleDelete = async () => {
    if (!selectedCompra) return;
    try {
      const res = await apiClient(`/api/compras/${selectedCompra.id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error();
      await fetchCompras();
      setIsDeleteModalOpen(false);
      setSelectedCompra(null);
      showMsg('Compra eliminada');
    } catch { showErr('Error al eliminar la compra'); }
  };

  const estadoStyle: Record<string, string> = {
    Recibido: 'bg-[oklch(0.696_0.17_162.48)]/20 text-[oklch(0.696_0.17_162.48)]',
    Pendiente: 'bg-[oklch(0.769_0.188_70.08)]/20 text-[oklch(0.769_0.188_70.08)]',
    Cancelado: 'bg-[oklch(0.396_0.141_25.723)] text-[oklch(0.645_0.246_16.439)]',
  };

  const filtered = compras.filter(c => {
    const matchSearch = c.proveedor.toLowerCase().includes(searchTerm.toLowerCase()) || c.id.toLowerCase().includes(searchTerm.toLowerCase());
    return matchSearch && (filterEstado === 'todos' || c.estado === filterEstado);
  });

  const totalInvertido = compras.reduce((sum, c) => sum + Number(c.total), 0);

  return (
    <div className="p-8 space-y-6">
      <div className="flex items-start justify-between">
        <div><h2 className="text-2xl text-white mb-1">Compras</h2><p className="text-muted-foreground">Gestión de órdenes de compra</p></div>
        <button onClick={() => { setFormMode('create'); setSelectedCompra(null); setIsFormModalOpen(true); }} className="bg-[oklch(0.488_0.243_264.376)] hover:bg-[oklch(0.438_0.243_264.376)] text-white px-4 py-2 rounded-lg transition-colors flex items-center gap-2">
          <Plus className="w-5 h-5" /> Nueva Compra
        </button>
      </div>

      <div className="grid grid-cols-3 gap-4">
        <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-4"><p className="text-sm text-muted-foreground mb-1">Total Invertido</p><p className="text-2xl text-white">S/. {totalInvertido.toLocaleString('es-PE', { minimumFractionDigits: 2 })}</p></div>
        <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-4"><p className="text-sm text-muted-foreground mb-1">Recibidas</p><p className="text-2xl text-[oklch(0.696_0.17_162.48)]">{compras.filter(c => c.estado === 'Recibido').length}</p></div>
        <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-4"><p className="text-sm text-muted-foreground mb-1">Pendientes</p><p className="text-2xl text-[oklch(0.769_0.188_70.08)]">{compras.filter(c => c.estado === 'Pendiente').length}</p></div>
      </div>

      {successMessage && (
        <div className="bg-[oklch(0.696_0.17_162.48)]/20 border border-[oklch(0.696_0.17_162.48)] rounded-lg p-4 flex items-center justify-between">
          <p className="text-[oklch(0.696_0.17_162.48)]">{successMessage}</p>
          <button onClick={() => setSuccessMessage('')}><X className="w-5 h-5 text-[oklch(0.696_0.17_162.48)]" /></button>
        </div>
      )}
      {errorMessage && (
        <div className="bg-destructive/20 border border-destructive rounded-lg p-4 flex items-center justify-between">
          <p className="text-destructive">{errorMessage}</p>
          <button onClick={() => setErrorMessage('')}><X className="w-5 h-5 text-destructive" /></button>
        </div>
      )}

      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm text-muted-foreground mb-2">Buscar</label>
            <div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" /><input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Proveedor o código..." className="w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg pl-11 pr-4 py-2 text-white placeholder:text-muted-foreground focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors" /></div>
          </div>
          <div>
            <label className="block text-sm text-muted-foreground mb-2">Estado</label>
            <div className="relative"><Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" /><select value={filterEstado} onChange={e => setFilterEstado(e.target.value)} className="w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg pl-11 pr-4 py-2 text-white focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors appearance-none"><option value="todos" className="bg-[oklch(0.269_0_0)]">Todos los estados</option><option value="Recibido" className="bg-[oklch(0.269_0_0)]">Recibido</option><option value="Pendiente" className="bg-[oklch(0.269_0_0)]">Pendiente</option><option value="Cancelado" className="bg-[oklch(0.269_0_0)]">Cancelado</option></select></div>
          </div>
        </div>
      </div>

      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl overflow-hidden">
        {loading ? (
          <div className="flex items-center justify-center py-20 gap-3"><Loader2 className="w-6 h-6 text-[oklch(0.488_0.243_264.376)] animate-spin" /><p className="text-muted-foreground">Cargando compras...</p></div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-[oklch(0.269_0_0)]">
                <tr>
                  <th className="text-left text-sm text-muted-foreground px-6 py-4">Código</th>
                  <th className="text-left text-sm text-muted-foreground px-6 py-4">Proveedor</th>
                  <th className="text-left text-sm text-muted-foreground px-6 py-4">Fecha</th>
                  <th className="text-right text-sm text-muted-foreground px-6 py-4">Total</th>
                  <th className="text-center text-sm text-muted-foreground px-6 py-4">Estado</th>
                  <th className="text-center text-sm text-muted-foreground px-6 py-4">Acciones</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[oklch(0.269_0_0)]">
                {filtered.map(compra => (
                  <tr key={compra.id} className="hover:bg-[oklch(0.269_0_0)]/50 transition-colors">
                    <td className="px-6 py-4 text-white text-sm">{compra.id}</td>
                    <td className="px-6 py-4 text-white">{compra.proveedor}</td>
                    <td className="px-6 py-4 text-muted-foreground">{new Date(compra.fecha).toLocaleDateString('es-PE')}</td>
                    <td className="px-6 py-4 text-white text-right">S/. {Number(compra.total).toFixed(2)}</td>
                    <td className="px-6 py-4 text-center"><span className={`px-3 py-1 rounded-full text-xs ${estadoStyle[compra.estado]}`}>{compra.estado}</span></td>
                    <td className="px-6 py-4">
                      <div className="flex items-center justify-center gap-2">
                        <button onClick={() => { setSelectedCompra(compra); setIsDetailsModalOpen(true); }} className="p-2 text-muted-foreground hover:text-[oklch(0.488_0.243_264.376)] transition-colors" title="Ver"><Eye className="w-4 h-4" /></button>
                        <button onClick={() => { setFormMode('edit'); setSelectedCompra(compra); setIsFormModalOpen(true); }} className="p-2 text-muted-foreground hover:text-[oklch(0.769_0.188_70.08)] transition-colors" title="Editar"><Edit className="w-4 h-4" /></button>
                        <button onClick={() => { setSelectedCompra(compra); setIsDeleteModalOpen(true); }} className="p-2 text-muted-foreground hover:text-destructive transition-colors" title="Eliminar"><Trash2 className="w-4 h-4" /></button>
                      </div>
                    </td>
                  </tr>
                ))}
                {filtered.length === 0 && <tr><td colSpan={6} className="px-6 py-12 text-center text-muted-foreground">No se encontraron compras</td></tr>}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <p className="text-sm text-muted-foreground">Mostrando {filtered.length} de {compras.length} compras</p>

      <CompraFormModal isOpen={isFormModalOpen} onClose={() => setIsFormModalOpen(false)} onSave={handleSave} compra={selectedCompra} mode={formMode} />
      <CompraDetailsModal isOpen={isDetailsModalOpen} onClose={() => setIsDetailsModalOpen(false)} compra={selectedCompra} />
      <DeleteModal isOpen={isDeleteModalOpen} onClose={() => setIsDeleteModalOpen(false)} onConfirm={handleDelete} nombre={selectedCompra?.proveedor || ''} />
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import {
  ShieldCheck, ShieldX, RefreshCw, Search,
  ChevronLeft, ChevronRight, Monitor, Clock, User,
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';

// Tipos 

interface RegistroLogin {
  id:          number;
  usuario_id:  number | null;
  email:       string;
  nombre:      string | null;
  rol:         string | null;
  resultado:   'Exitoso' | 'Fallido';
  ip_address:  string | null;
  detalle:     string | null;
  fecha_hora:  string;
}

interface Respuesta {
  total:      number;
  pagina:     number;
  limite:     number;
  registros:  RegistroLogin[];
}

const API = 'http://localhost:3001/api';
const LIMITE = 15;

// Helpers 

function formatFecha(iso: string) {
  const d = new Date(iso);
  return d.toLocaleString('es-PE', {
    day:    '2-digit', month: '2-digit', year: 'numeric',
    hour:   '2-digit', minute: '2-digit', second: '2-digit',
  });
}

const ROL_COLOR: Record<string, string> = {
  Administrador: 'text-[oklch(0.488_0.243_264.376)] bg-[oklch(0.488_0.243_264.376)]/10',
  Supervisor:    'text-[oklch(0.769_0.188_70.08)]   bg-[oklch(0.769_0.188_70.08)]/10',
  Vendedor:      'text-[oklch(0.696_0.17_162.48)]   bg-[oklch(0.696_0.17_162.48)]/10',
};

// Componente

export default function HistorialLogin() {
  const { token } = useAuth();

  const [data,       setData]       = useState<Respuesta | null>(null);
  const [loading,    setLoading]    = useState(false);
  const [error,      setError]      = useState('');
  const [pagina,     setPagina]     = useState(1);
  const [filtroEmail,   setFiltroEmail]   = useState('');
  const [filtroResultado, setFiltroResultado] = useState('');

  // Carga de datos
  const cargar = useCallback(async (pag: number, email: string, resultado: string) => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({
        pagina:  String(pag),
        limite:  String(LIMITE),
        ...(email     ? { email }     : {}),
        ...(resultado ? { resultado } : {}),
      });

      const res = await fetch(`${API}/auth/historial?${params}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        const d = await res.json();
        throw new Error(d.error || 'Error al cargar historial.');
      }
      const json: Respuesta = await res.json();
      setData(json);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, [token]);

  useEffect(() => {
    cargar(pagina, filtroEmail, filtroResultado);
  }, [pagina, cargar, filtroEmail, filtroResultado]);

  const totalPaginas = data ? Math.ceil(data.total / LIMITE) : 1;

  const aplicarFiltros = () => {
    setPagina(1);
    cargar(1, filtroEmail, filtroResultado);
  };

  // Estadísticas rápidas
  const exitosos = data?.registros.filter(r => r.resultado === 'Exitoso').length ?? 0;
  const fallidos = data?.registros.filter(r => r.resultado === 'Fallido').length ?? 0;

  return (
    <div className="p-6 space-y-6">

      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl text-white">Historial de Accesos</h2>
          <p className="text-sm text-muted-foreground mt-1">
            Registro de todos los intentos de inicio de sesión al sistema
          </p>
        </div>
        <button
          onClick={() => cargar(pagina, filtroEmail, filtroResultado)}
          disabled={loading}
          className="flex items-center gap-2 px-4 py-2 bg-[oklch(0.269_0_0)] hover:bg-[oklch(0.3_0_0)] text-white rounded-lg transition-colors disabled:opacity-50"
        >
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
          Actualizar
        </button>
      </div>

      {/* Tarjetas resumen */}
      {data && (
        <div className="grid grid-cols-3 gap-4">
          <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-4 flex items-center gap-4">
            <div className="w-10 h-10 rounded-lg bg-[oklch(0.488_0.243_264.376)]/10 flex items-center justify-center">
              <Clock className="w-5 h-5 text-[oklch(0.488_0.243_264.376)]" />
            </div>
            <div>
              <p className="text-2xl text-white font-semibold">{data.total}</p>
              <p className="text-xs text-muted-foreground">Total registros</p>
            </div>
          </div>
          <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-4 flex items-center gap-4">
            <div className="w-10 h-10 rounded-lg bg-green-500/10 flex items-center justify-center">
              <ShieldCheck className="w-5 h-5 text-green-400" />
            </div>
            <div>
              <p className="text-2xl text-white font-semibold">{exitosos}</p>
              <p className="text-xs text-muted-foreground">Exitosos (pág. actual)</p>
            </div>
          </div>
          <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-4 flex items-center gap-4">
            <div className="w-10 h-10 rounded-lg bg-red-500/10 flex items-center justify-center">
              <ShieldX className="w-5 h-5 text-red-400" />
            </div>
            <div>
              <p className="text-2xl text-white font-semibold">{fallidos}</p>
              <p className="text-xs text-muted-foreground">Fallidos (pág. actual)</p>
            </div>
          </div>
        </div>
      )}

      {/* Filtros */}
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-4 flex flex-wrap gap-3 items-end">
        <div className="flex-1 min-w-[200px]">
          <label className="block text-xs text-muted-foreground mb-1.5">Buscar por email</label>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <input
              type="text"
              value={filtroEmail}
              onChange={(e) => setFiltroEmail(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && aplicarFiltros()}
              placeholder="usuario@farmacia.com"
              className="w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg pl-9 pr-4 py-2 text-sm text-white placeholder:text-muted-foreground focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors"
            />
          </div>
        </div>
        <div className="min-w-[160px]">
          <label className="block text-xs text-muted-foreground mb-1.5">Resultado</label>
          <select
            value={filtroResultado}
            onChange={(e) => setFiltroResultado(e.target.value)}
            className="w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors"
          >
            <option value="">Todos</option>
            <option value="Exitoso">Exitoso</option>
            <option value="Fallido">Fallido</option>
          </select>
        </div>
        <button
          onClick={aplicarFiltros}
          className="px-4 py-2 bg-[oklch(0.488_0.243_264.376)] hover:bg-[oklch(0.438_0.243_264.376)] text-white text-sm rounded-lg transition-colors"
        >
          Buscar
        </button>
      </div>

      {/* Error */}
      {error && (
        <div className="bg-red-500/10 border border-red-500/30 rounded-lg px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}

      {/* Tabla */}
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[oklch(0.269_0_0)]">
                <th className="text-left px-4 py-3 text-xs text-muted-foreground font-medium">Fecha / Hora</th>
                <th className="text-left px-4 py-3 text-xs text-muted-foreground font-medium">Usuario</th>
                <th className="text-left px-4 py-3 text-xs text-muted-foreground font-medium">Rol</th>
                <th className="text-left px-4 py-3 text-xs text-muted-foreground font-medium">Resultado</th>
                <th className="text-left px-4 py-3 text-xs text-muted-foreground font-medium">IP</th>
                <th className="text-left px-4 py-3 text-xs text-muted-foreground font-medium">Detalle</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan={6} className="text-center py-12 text-muted-foreground">
                    <RefreshCw className="w-5 h-5 animate-spin mx-auto mb-2" />
                    Cargando registros…
                  </td>
                </tr>
              ) : data?.registros.length === 0 ? (
                <tr>
                  <td colSpan={6} className="text-center py-12 text-muted-foreground">
                    No se encontraron registros con los filtros aplicados.
                  </td>
                </tr>
              ) : (
                data?.registros.map((r) => (
                  <tr
                    key={r.id}
                    className="border-b border-[oklch(0.269_0_0)] hover:bg-[oklch(0.23_0_0)] transition-colors"
                  >
                    {/* Fecha */}
                    <td className="px-4 py-3 text-white whitespace-nowrap font-mono text-xs">
                      {formatFecha(r.fecha_hora)}
                    </td>

                    {/* Usuario */}
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-2">
                        <User className="w-3.5 h-3.5 text-muted-foreground flex-shrink-0" />
                        <div>
                          {r.nombre && (
                            <p className="text-white text-xs font-medium">{r.nombre}</p>
                          )}
                          <p className="text-muted-foreground text-xs">{r.email}</p>
                        </div>
                      </div>
                    </td>

                    {/* Rol */}
                    <td className="px-4 py-3">
                      {r.rol ? (
                        <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${ROL_COLOR[r.rol] ?? 'text-muted-foreground bg-muted'}`}>
                          {r.rol}
                        </span>
                      ) : (
                        <span className="text-xs text-muted-foreground">—</span>
                      )}
                    </td>

                    {/* Resultado */}
                    <td className="px-4 py-3">
                      {r.resultado === 'Exitoso' ? (
                        <span className="inline-flex items-center gap-1.5 text-xs font-medium text-green-400 bg-green-500/10 px-2.5 py-1 rounded-full">
                          <ShieldCheck className="w-3 h-3" />
                          Exitoso
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1.5 text-xs font-medium text-red-400 bg-red-500/10 px-2.5 py-1 rounded-full">
                          <ShieldX className="w-3 h-3" />
                          Fallido
                        </span>
                      )}
                    </td>

                    {/* IP */}
                    <td className="px-4 py-3">
                      <span className="flex items-center gap-1.5 text-xs text-muted-foreground font-mono">
                        <Monitor className="w-3 h-3" />
                        {r.ip_address || '—'}
                      </span>
                    </td>

                    {/* Detalle */}
                    <td className="px-4 py-3 text-xs text-muted-foreground">
                      {r.detalle || '—'}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Paginación */}
        {data && totalPaginas > 1 && (
          <div className="px-4 py-3 border-t border-[oklch(0.269_0_0)] flex items-center justify-between">
            <p className="text-xs text-muted-foreground">
              Mostrando {((pagina - 1) * LIMITE) + 1}–{Math.min(pagina * LIMITE, data.total)} de {data.total} registros
            </p>
            <div className="flex items-center gap-2">
              <button
                disabled={pagina <= 1}
                onClick={() => setPagina(p => p - 1)}
                className="p-1.5 rounded-lg hover:bg-[oklch(0.269_0_0)] text-muted-foreground disabled:opacity-40 transition-colors"
              >
                <ChevronLeft className="w-4 h-4" />
              </button>
              <span className="text-xs text-white px-2">
                {pagina} / {totalPaginas}
              </span>
              <button
                disabled={pagina >= totalPaginas}
                onClick={() => setPagina(p => p + 1)}
                className="p-1.5 rounded-lg hover:bg-[oklch(0.269_0_0)] text-muted-foreground disabled:opacity-40 transition-colors"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { apiClient } from '../utils/apiClient';
import { Search, Filter, Plus, Edit, Trash2, AlertCircle, Eye, X, Loader2 } from 'lucide-react';
import ProductoFormModal from './ProductoFormModal';
import ProductoDetailsModal from './ProductoDetailsModal';
import DeleteConfirmModal from './DeleteConfirmModal';



interface Producto {
  id: string;
  nombre: string;
  descripcion?: string;
  laboratorio: string;
  lote: string;
  stock: number;
  stockMinimo: number;
  precio: number;
  vencimiento: string;
  estado: 'normal' | 'bajo' | 'agotado' | 'vencido';
  categoria?: string;
}

export default function Inventario() {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterLab, setFilterLab] = useState('todos');
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [formMode, setFormMode] = useState<'create' | 'edit'>('create');
  const [selectedProducto, setSelectedProducto] = useState<Producto | null>(null);
  const [successMessage, setSuccessMessage] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const [productos, setProductos] = useState<Producto[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchProductos = async () => {
    try {
      setLoading(true);
      const res = await apiClient('/api/productos');
      if (!res.ok) throw new Error();
      const data = await res.json();
      setProductos(data.map((p: any) => ({ ...p, stockMinimo: p.stock_minimo ?? p.stockMinimo })));
    } catch {
      setErrorMessage('No se pudo conectar con el servidor');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchProductos(); }, []);

  const showMsg = (msg: string) => { setSuccessMessage(msg); setTimeout(() => setSuccessMessage(''), 3000); };
  const showErr = (msg: string) => { setErrorMessage(msg); setTimeout(() => setErrorMessage(''), 3000); };

  const determinarEstado = (p: Producto): Producto['estado'] => {
    if (p.stock === 0) return 'agotado';
    if (p.stock < p.stockMinimo) return 'bajo';
    if (Math.ceil((new Date(p.vencimiento).getTime() - Date.now()) / 86400000) <= 12) return 'vencido';
    return 'normal';
  };

  const handleCreate = async (data: Omit<Producto, 'id' | 'estado'>) => {
    const id = `P${String(productos.length + 1).padStart(3, '0')}`;
    const estado = determinarEstado({ ...data, id, estado: 'normal' });
    try {
     const res = await apiClient('/api/productos', {
        method: 'POST',
        body: JSON.stringify({
          ...data,
          id,
          estado,
          stock_minimo: data.stockMinimo,
        }),
      });
      if (!res.ok) throw new Error();
      await fetchProductos();
      showMsg('Producto creado exitosamente');
    } catch { showErr('Error al crear el producto'); }
  };

  const handleEdit = async (data: Producto) => {
    const estado = determinarEstado(data);
    try {
      const res = await apiClient(`/api/productos/${data.id}`, {
        method: 'PUT',
        body: JSON.stringify({
          ...data,
          estado,
          stock_minimo: data.stockMinimo,
        }),
      });
      if (!res.ok) throw new Error();
      await fetchProductos();
      showMsg('Producto actualizado correctamente');
    } catch { showErr('Error al actualizar el producto'); }
  };

  const handleDelete = async () => {
    if (!selectedProducto) return;
    try {
      const res = await apiClient(`/api/productos/${selectedProducto.id}`, {
        method: 'DELETE',
      });
      if (!res.ok) throw new Error();
      await fetchProductos();
      setIsDeleteModalOpen(false);
      setSelectedProducto(null);
      showMsg('Producto eliminado');
    } catch { showErr('Error al eliminar el producto'); }
  };

  const handleSave = (producto: any) => formMode === 'create' ? handleCreate(producto) : handleEdit(producto);
  const openCreateModal = () => { setFormMode('create'); setSelectedProducto(null); setIsFormModalOpen(true); };
  const openEditModal = (p: Producto) => { setFormMode('edit'); setSelectedProducto(p); setIsFormModalOpen(true); };
  const openDetailsModal = (p: Producto) => { setSelectedProducto(p); setIsDetailsModalOpen(true); };
  const openDeleteModal = (p: Producto) => { setSelectedProducto(p); setIsDeleteModalOpen(true); };

  const laboratorios = ['todos', ...Array.from(new Set(productos.map(p => p.laboratorio)))];
  const filteredProducts = productos.filter(p => {
    const matchSearch = p.nombre.toLowerCase().includes(searchTerm.toLowerCase()) || p.id.toLowerCase().includes(searchTerm.toLowerCase());
    return matchSearch && (filterLab === 'todos' || p.laboratorio === filterLab);
  });

  const getEstadoBadge = (estado: string) => {
    const badges: Record<string, string> = {
      normal: 'bg-[oklch(0.696_0.17_162.48)]/20 text-[oklch(0.696_0.17_162.48)]',
      bajo: 'bg-[oklch(0.769_0.188_70.08)]/20 text-[oklch(0.769_0.188_70.08)]',
      agotado: 'bg-[oklch(0.396_0.141_25.723)] text-[oklch(0.645_0.246_16.439)]',
      vencido: 'bg-[oklch(0.396_0.141_25.723)] text-[oklch(0.645_0.246_16.439)]',
    };
    const labels: Record<string, string> = { normal: 'Normal', bajo: 'Stock Bajo', agotado: 'Agotado', vencido: 'Vencido' };
    return <span className={`px-3 py-1 rounded-full text-xs ${badges[estado]}`}>{labels[estado]}</span>;
  };

  const isVencido = (fecha: string) => Math.ceil((new Date(fecha).getTime() - Date.now()) / 86400000) <= 12;

  return (
    <div className="p-8 space-y-6">
      <div className="flex items-start justify-between">
        <div>
          <h2 className="text-2xl text-white mb-1">Inventario</h2>
          <p className="text-muted-foreground">Gestión de stock en tiempo real</p>
        </div>
        <button onClick={openCreateModal} className="bg-[oklch(0.488_0.243_264.376)] hover:bg-[oklch(0.438_0.243_264.376)] text-white px-4 py-2 rounded-lg transition-colors flex items-center gap-2">
          <Plus className="w-5 h-5" /> Nuevo Producto
        </button>
      </div>

      {successMessage && (
        <div className="bg-[oklch(0.696_0.17_162.48)]/20 border border-[oklch(0.696_0.17_162.48)] rounded-lg p-4 flex items-center justify-between">
          <p className="text-[oklch(0.696_0.17_162.48)]">{successMessage}</p>
          <button onClick={() => setSuccessMessage('')}><X className="w-5 h-5 text-[oklch(0.696_0.17_162.48)]" /></button>
        </div>
      )}
      {errorMessage && (
        <div className="bg-destructive/20 border border-destructive rounded-lg p-4 flex items-center justify-between">
          <p className="text-destructive">{errorMessage}</p>
          <button onClick={() => setErrorMessage('')}><X className="w-5 h-5 text-destructive" /></button>
        </div>
      )}

      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm text-muted-foreground mb-2">Buscar</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
              <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Nombre o código..." className="w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg pl-11 pr-4 py-2 text-white placeholder:text-muted-foreground focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors" />
            </div>
          </div>
          <div>
            <label className="block text-sm text-muted-foreground mb-2">Laboratorio</label>
            <div className="relative">
              <Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
              <select value={filterLab} onChange={e => setFilterLab(e.target.value)} className="w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg pl-11 pr-4 py-2 text-white focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors appearance-none">
                {laboratorios.map(lab => <option key={lab} value={lab} className="bg-[oklch(0.269_0_0)]">{lab === 'todos' ? 'Todos los laboratorios' : lab}</option>)}
              </select>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl overflow-hidden">
        {loading ? (
          <div className="flex items-center justify-center py-20 gap-3">
            <Loader2 className="w-6 h-6 text-[oklch(0.488_0.243_264.376)] animate-spin" />
            <p className="text-muted-foreground">Cargando productos...</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-[oklch(0.269_0_0)]">
                <tr>
                  <th className="text-left text-sm text-muted-foreground px-6 py-4">Código</th>
                  <th className="text-left text-sm text-muted-foreground px-6 py-4">Producto</th>
                  <th className="text-left text-sm text-muted-foreground px-6 py-4">Laboratorio</th>
                  <th className="text-left text-sm text-muted-foreground px-6 py-4">Lote</th>
                  <th className="text-center text-sm text-muted-foreground px-6 py-4">Stock</th>
                  <th className="text-right text-sm text-muted-foreground px-6 py-4">Precio</th>
                  <th className="text-left text-sm text-muted-foreground px-6 py-4">Vencimiento</th>
                  <th className="text-center text-sm text-muted-foreground px-6 py-4">Estado</th>
                  <th className="text-center text-sm text-muted-foreground px-6 py-4">Acciones</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[oklch(0.269_0_0)]">
                {filteredProducts.map(producto => (
                  <tr key={producto.id} className="hover:bg-[oklch(0.269_0_0)]/50 transition-colors">
                    <td className="px-6 py-4"><span className="text-white text-sm">{producto.id}</span></td>
                    <td className="px-6 py-4"><p className="text-white">{producto.nombre}</p></td>
                    <td className="px-6 py-4"><span className="text-white text-sm">{producto.laboratorio}</span></td>
                    <td className="px-6 py-4"><span className="text-muted-foreground text-sm">{producto.lote}</span></td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex flex-col items-center">
                        <span className="text-white">{producto.stock}</span>
                        <span className="text-xs text-muted-foreground">mín: {producto.stockMinimo}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right"><span className="text-white">S/. {Number(producto.precio).toFixed(2)}</span></td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        {isVencido(producto.vencimiento) && <AlertCircle className="w-4 h-4 text-[oklch(0.645_0.246_16.439)]" />}
                        <span className={`text-sm ${isVencido(producto.vencimiento) ? 'text-[oklch(0.645_0.246_16.439)]' : 'text-white'}`}>
                          {new Date(producto.vencimiento).toLocaleDateString('es-PE')}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">{getEstadoBadge(producto.estado)}</td>
                    <td className="px-6 py-4">
                      <div className="flex items-center justify-center gap-2">
                        <button onClick={() => openDetailsModal(producto)} className="p-2 text-muted-foreground hover:text-[oklch(0.488_0.243_264.376)] transition-colors" title="Ver detalles"><Eye className="w-4 h-4" /></button>
                        <button onClick={() => openEditModal(producto)} className="p-2 text-muted-foreground hover:text-[oklch(0.769_0.188_70.08)] transition-colors" title="Editar"><Edit className="w-4 h-4" /></button>
                        <button onClick={() => openDeleteModal(producto)} className="p-2 text-muted-foreground hover:text-destructive transition-colors" title="Eliminar"><Trash2 className="w-4 h-4" /></button>
                      </div>
                    </td>
                  </tr>
                ))}
                {filteredProducts.length === 0 && (
                  <tr><td colSpan={9} className="px-6 py-12 text-center text-muted-foreground">No se encontraron productos</td></tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <div className="flex items-center justify-between text-sm text-muted-foreground">
        <p>Mostrando {filteredProducts.length} de {productos.length} productos</p>
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-[oklch(0.696_0.17_162.48)]"></div><span>Normal</span></div>
          <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-[oklch(0.769_0.188_70.08)]"></div><span>Stock Bajo</span></div>
          <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-[oklch(0.645_0.246_16.439)]"></div><span>Crítico</span></div>
        </div>
      </div>

      <ProductoFormModal isOpen={isFormModalOpen} onClose={() => setIsFormModalOpen(false)} onSave={handleSave} producto={selectedProducto} mode={formMode} />
      <ProductoDetailsModal isOpen={isDetailsModalOpen} onClose={() => setIsDetailsModalOpen(false)} producto={selectedProducto} />
      <DeleteConfirmModal isOpen={isDeleteModalOpen} onClose={() => setIsDeleteModalOpen(false)} onConfirm={handleDelete} productName={selectedProducto?.nombre || ''} />
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { Lock, User, AlertCircle, Loader2, ShieldOff, Clock } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

const MAX_ATTEMPTS   = 3;
const LOCKOUT_SECS   = 30; 

export default function Login() {
  const { login } = useAuth();

  const [email,    setEmail]    = useState('');
  const [password, setPassword] = useState('');
  const [error,    setError]    = useState('');
  const [loading,  setLoading]  = useState(false);

  // Control de intentos fallidos
  const [attempts,     setAttempts]     = useState(0);      
  const [lockedOut,    setLockedOut]    = useState(false);  
  const [countdown,    setCountdown]    = useState(0);       

  const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Iniciar bloqueo 
  const startLockout = () => {
    setLockedOut(true);
    setCountdown(LOCKOUT_SECS);
    setError('');

    countdownRef.current = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          clearInterval(countdownRef.current!);
          setLockedOut(false);
          setAttempts(0);
          setError('');
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  // Limpiar interval al desmontar
  useEffect(() => {
    return () => {
      if (countdownRef.current) clearInterval(countdownRef.current);
    };
  }, []);

  // Submit 
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (lockedOut) return;

    setError('');

    if (!email.trim() || !password.trim()) {
      setError('Por favor ingresa tu email y contraseña.');
      return;
    }

    setLoading(true);
    try {
      await login(email.trim(), password);
      setAttempts(0);
    } catch (err: any) {
      const newAttempts = attempts + 1;
      setAttempts(newAttempts);

      if (newAttempts >= MAX_ATTEMPTS) {
        startLockout();
      } else {
        setError(err.message || 'Credenciales incorrectas.');
      }
    } finally {
      setLoading(false);
    }
  };

  // Intentos restantes antes de bloqueo 
  const attemptsLeft = MAX_ATTEMPTS - attempts;

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <div className="w-full max-w-md">

        {/* Logo & Title */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-[oklch(0.488_0.243_264.376)] mb-4">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
            </svg>
          </div>
          <h1 className="text-3xl text-white mb-2">Farmacia Sanet</h1>
          <p className="text-muted-foreground">Sistema de Gestión de Ventas e Inventario</p>
        </div>

        {/* Login Form */}
        <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl p-8">
          <form onSubmit={handleSubmit} className="space-y-6">

            {/* ── Bloqueo activo ─────────────────────────────────────────── */}
            {lockedOut && (
              <div className="flex flex-col items-center gap-3 bg-orange-500/10 border border-orange-500/40 rounded-lg px-4 py-5 text-center">
                <ShieldOff className="w-8 h-8 text-orange-400" />
                <div>
                  <p className="text-sm font-semibold text-orange-300">Cuenta bloqueada temporalmente</p>
                  <p className="text-xs text-orange-400/80 mt-1">
                    Demasiados intentos fallidos. Espera antes de intentarlo de nuevo.
                  </p>
                </div>
                <div className="flex items-center gap-2 bg-orange-500/20 rounded-full px-4 py-2 mt-1">
                  <Clock className="w-4 h-4 text-orange-300" />
                  <span className="text-lg font-mono font-bold text-orange-200">
                    {countdown}s
                  </span>
                </div>
              </div>
            )}

            {/* ── Error normal ───────────────────────────────────────────── */}
            {error && !lockedOut && (
              <div className="flex flex-col gap-1 bg-red-500/10 border border-red-500/30 rounded-lg px-4 py-3">
                <div className="flex items-center gap-3">
                  <AlertCircle className="w-5 h-5 text-red-400 flex-shrink-0" />
                  <p className="text-sm text-red-400">{error}</p>
                </div>
                {attempts > 0 && attempts < MAX_ATTEMPTS && (
                  <p className="text-xs text-red-400/70 pl-8">
                    Intentos restantes: <span className="font-semibold text-red-300">{attemptsLeft}</span> de {MAX_ATTEMPTS}
                  </p>
                )}
              </div>
            )}

            {/* Email */}
            <div>
              <label className="block text-sm text-muted-foreground mb-2">Email</label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="usuario@farmacia.com"
                  disabled={loading || lockedOut}
                  className="w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg pl-11 pr-4 py-3 text-white placeholder:text-muted-foreground focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                />
              </div>
            </div>

            {/* Password */}
            <div>
              <label className="block text-sm text-muted-foreground mb-2">Contraseña</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Ingresa tu contraseña"
                  disabled={loading || lockedOut}
                  className="w-full bg-[oklch(0.269_0_0)] border border-[oklch(0.269_0_0)] rounded-lg pl-11 pr-4 py-3 text-white placeholder:text-muted-foreground focus:outline-none focus:border-[oklch(0.488_0.243_264.376)] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                />
              </div>
            </div>

            {/* Indicador de intentos (solo tras el primer fallo) */}
            {attempts > 0 && !lockedOut && (
              <div className="flex gap-1.5 justify-center">
                {Array.from({ length: MAX_ATTEMPTS }).map((_, i) => (
                  <div
                    key={i}
                    className={`h-1.5 flex-1 rounded-full transition-colors ${
                      i < attempts ? 'bg-red-500' : 'bg-[oklch(0.269_0_0)]'
                    }`}
                  />
                ))}
              </div>
            )}

            <button
              type="submit"
              disabled={loading || lockedOut}
              className="w-full flex items-center justify-center gap-2 bg-[oklch(0.488_0.243_264.376)] hover:bg-[oklch(0.438_0.243_264.376)] text-white py-3 rounded-lg transition-colors disabled:opacity-60 disabled:cursor-not-allowed"
            >
              {loading ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  <span>Iniciando sesión…</span>
                </>
              ) : lockedOut ? (
                <>
                  <Clock className="w-5 h-5" />
                  <span>Bloqueado ({countdown}s)</span>
                </>
              ) : (
                <span>Iniciar Sesión</span>
              )}
            </button>
          </form>
        </div>

        <p className="text-center text-xs text-muted-foreground mt-6">
          © 2026 Farmacia Sanet. Todos los derechos reservados.
        </p>
      </div>
    </div>
  );
}

import { X, Calendar, Package, DollarSign, AlertCircle } from 'lucide-react';

interface Producto {
  id: string;
  nombre: string;
  descripcion?: string;
  laboratorio: string;
  lote: string;
  precio: number;
  stock: number;
  stockMinimo: number;
  vencimiento: string;
  estado: 'normal' | 'bajo' | 'agotado' | 'vencido';
  categoria?: string;
}

interface ProductoDetailsModalProps {
  isOpen: boolean;
  onClose: () => void;
  producto: Producto | null;
}

export default function ProductoDetailsModal({
  isOpen,
  onClose,
  producto
}: ProductoDetailsModalProps) {
  if (!isOpen || !producto) return null;

  const getEstadoBadge = (estado: string) => {
    const badges = {
      normal: 'bg-[oklch(0.696_0.17_162.48)]/20 text-[oklch(0.696_0.17_162.48)]',
      bajo: 'bg-[oklch(0.769_0.188_70.08)]/20 text-[oklch(0.769_0.188_70.08)]',
      agotado: 'bg-[oklch(0.396_0.141_25.723)] text-[oklch(0.645_0.246_16.439)]',
      vencido: 'bg-[oklch(0.396_0.141_25.723)] text-[oklch(0.645_0.246_16.439)]',
    };

    const labels = {
      normal: 'Normal',
      bajo: 'Stock Bajo',
      agotado: 'Agotado',
      vencido: 'Vencido',
    };

    return (
      <span className={`px-3 py-1 rounded-full text-xs ${badges[estado as keyof typeof badges]}`}>
        {labels[estado as keyof typeof labels]}
      </span>
    );
  };

  const isVencido = (fecha: string) => {
    const vencimiento = new Date(fecha);
    const hoy = new Date();
    const diasDiferencia = Math.ceil((vencimiento.getTime() - hoy.getTime()) / (1000 * 60 * 60 * 24));
    return diasDiferencia <= 12;
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-[oklch(0.205_0_0)] border border-[oklch(0.269_0_0)] rounded-xl max-w-2xl w-full">
        {/* Header */}
        <div className="border-b border-[oklch(0.269_0_0)] px-6 py-4 flex items-center justify-between">
          <h2 className="text-xl text-white">Detalles del Producto</h2>
          <button
            onClick={onClose}
            className="text-muted-foreground hover:text-white transition-colors"
          >
