          )}
        </div>
        <div className="border-t border-[oklch(0.269_0_0)] px-6 py-4">
          <button onClick={onClose} className="w-full bg-[oklch(0.269_0_0)] hover:bg-[oklch(0.318_0_0)] text-white py-3 rounded-lg transition-colors">Cerrar</button>
        </div>
      </div>
    </div>
  );
}

