      </div>

      <p className="text-sm text-muted-foreground">Mostrando {filtered.length} de {usuarios.length} usuarios</p>

      <UsuarioFormModal
        isOpen={isFormOpen}
        onClose={() => { setIsFormOpen(false); setSelectedUsuario(null); }}
